import{_ as r,o as t,c as i,ag as a}from"./chunks/framework.NkyI2htt.js";const o="/cours/assets/tableau.DfcntXDL.png",n="/cours/assets/tableau-entreprise.DFzh8iTj.png",h=JSON.parse('{"title":"TP3 — Rapport Word sur le milieu de l’informatique","description":"","frontmatter":{"title":"TP3 — Rapport Word sur le milieu de l’informatique"},"headers":[],"relativePath":"travaux/tp3-word-profession.md","filePath":"travaux/tp3-word-profession.md"}'),s={name:"travaux/tp3-word-profession.md"};function l(u,e,p,d,c,g){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="travail-pratique-3-—-rapport-word" tabindex="-1">Travail pratique 3 — Rapport Word <a class="header-anchor" href="#travail-pratique-3-—-rapport-word" aria-label="Permalink to &quot;Travail pratique 3 — Rapport Word&quot;">​</a></h1><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Ce travail comporte deux parties :</p><ul><li><strong>Partie A :</strong> créer un <strong>modèle de rapport Word professionnel</strong> réutilisable dans d’autres cours.</li><li><strong>Partie B :</strong> utiliser ce modèle pour rédiger un <strong>rapport de recherche sur des entreprises du domaine informatique</strong>.</li></ul><p>Ce travail a deux objectifs pédagogiques :</p><ol><li>apprendre à <strong>produire un document professionnel avec Microsoft Word</strong> ;</li><li>mieux comprendre <strong>le milieu de travail en informatique</strong>, notamment les entreprises, les métiers et les compétences recherchées.</li></ol><p>Les recherches réalisées dans ce travail vous aideront également à <strong>préparer les visites d’entreprises prévues durant la session</strong>.</p><hr><h2 id="tldr" tabindex="-1">TLDR <a class="header-anchor" href="#tldr" aria-label="Permalink to &quot;TLDR&quot;">​</a></h2><h3 id="partie-a" tabindex="-1">Partie A <a class="header-anchor" href="#partie-a" aria-label="Permalink to &quot;Partie A&quot;">​</a></h3><p>Créer un <strong>modèle Word (.dotx)</strong> respectant les normes de présentation demandées.</p><h3 id="partie-b" tabindex="-1">Partie B <a class="header-anchor" href="#partie-b" aria-label="Permalink to &quot;Partie B&quot;">​</a></h3><p>Utiliser ce modèle pour rédiger un <strong>rapport sur trois organisations du milieu informatique et numérique</strong> :</p><ul><li><strong>deux sujets</strong> à choisir parmi <strong>les entreprises visitées pour votre groupe</strong> et le <a href="https://www.quebec.ca/gouvernement/ministeres-organismes/cybersecurite-numerique" target="_blank" rel="noreferrer">Ministère de la Cybersécurité et du Numérique (qui viendra visiter les deux groupes en classe)</a></li><li>une entreprise de votre choix</li></ul><hr><h2 id="partie-a-—-creation-du-modele-word" tabindex="-1">Partie A — Création du modèle Word <a class="header-anchor" href="#partie-a-—-creation-du-modele-word" aria-label="Permalink to &quot;Partie A — Création du modèle Word&quot;">​</a></h2><p><strong>Modèle à suivre : <a href="./../tps/Modèle (Partie A).pdf" target="_blank" rel="noopener">Modèle (Partie A).pdf</a></strong></p><h3 id="creation-du-document" tabindex="-1">Création du document <a class="header-anchor" href="#creation-du-document" aria-label="Permalink to &quot;Création du document&quot;">​</a></h3><p>Créer un document Word qui servira de <strong>modèle de rapport</strong>.</p><p>Ce document doit contenir <strong>du contenu générique</strong>, car il s’agit d’un modèle et non d’un vrai rapport.</p><p>Vous pouvez utiliser du <strong>texte de substitution (Lorem Ipsum)</strong> pour remplir certaines sections : <a href="https://loremipsum.io/" target="_blank" rel="noreferrer">loremipsum.io</a>.</p><hr><h3 id="structure-du-document" tabindex="-1">Structure du document <a class="header-anchor" href="#structure-du-document" aria-label="Permalink to &quot;Structure du document&quot;">​</a></h3><p>Votre modèle doit contenir les pages suivantes.</p><h4 id="_1-page-de-presentation" tabindex="-1">1) Page de présentation <a class="header-anchor" href="#_1-page-de-presentation" aria-label="Permalink to &quot;1) Page de présentation&quot;">​</a></h4><p>Contenu requis :</p><ul><li>logo du <strong>Cégep Garneau</strong></li><li>texte : <strong>Département d’informatique</strong></li><li>travail no. X</li><li>titre du travail</li><li>présenté par : <em>Votre nom</em></li><li>cours : <strong>420-06A-FX — Milieu de l’informatique</strong></li><li>nom du professeur</li></ul><p>La page doit contenir <strong>une bordure de page</strong>.</p><hr><h4 id="_2-page-blanche" tabindex="-1">2) Page blanche <a class="header-anchor" href="#_2-page-blanche" aria-label="Permalink to &quot;2) Page blanche&quot;">​</a></h4><p>La page suivante doit être <strong>complètement vide</strong>.</p><p>⚠️ Ne pas simplement ajouter des lignes vides.</p><hr><h4 id="_3-table-des-matieres" tabindex="-1">3) Table des matières <a class="header-anchor" href="#_3-table-des-matieres" aria-label="Permalink to &quot;3) Table des matières&quot;">​</a></h4><p>La table des matières doit :</p><ul><li>être <strong>automatique</strong></li><li>pouvoir être <strong>mise à jour</strong></li><li>être seule sur sa page</li><li>utiliser une <strong>numérotation romaine</strong></li><li>être centrée au bas de la page</li></ul><p>Les marges de cette page doivent être <strong>larges</strong>.</p><hr><h4 id="_4-pages-de-contenu" tabindex="-1">4) Pages de contenu <a class="header-anchor" href="#_4-pages-de-contenu" aria-label="Permalink to &quot;4) Pages de contenu&quot;">​</a></h4><p>Le modèle doit contenir :</p><ul><li><strong>3 titres de niveau 1</strong></li><li><strong>3 titres de niveau 2</strong> (sous-titre)</li><li><strong>3 titres de niveau 3</strong> (sous-sous-titre)</li></ul><p>Les titres doivent être accompagné de contenus textes et images (voir les éléments obligatoire ci-bas).</p><p><strong>Référez-vous au <a href="./../tps/Modèle (Partie A).pdf" target="_blank" rel="noopener">Modèle (Partie A).pdf</a>.</strong></p><h4 id="_5-bibliographie" tabindex="-1">5) Bibliographie <a class="header-anchor" href="#_5-bibliographie" aria-label="Permalink to &quot;5) Bibliographie&quot;">​</a></h4><p>Ajouter une page <strong>Bibliographie</strong> contenant une <strong>bibliographie fictive</strong>.</p><p>Utiliser le <strong>style APA</strong> pour la citation et la bibliographie.</p><p>Elle sera remplacée par de vraies sources dans la partie B.</p><hr><h3 id="elements-obligatoires" tabindex="-1">Éléments obligatoires <a class="header-anchor" href="#elements-obligatoires" aria-label="Permalink to &quot;Éléments obligatoires&quot;">​</a></h3><p>Votre modèle doit également contenir :</p><h4 id="citation" tabindex="-1">Citation <a class="header-anchor" href="#citation" aria-label="Permalink to &quot;Citation&quot;">​</a></h4><p>Insérer <strong>au moins une citation</strong> dans le document (elle peut être fictive).</p><p>L&#39;exemple de citation se trouve à la <strong>page 6</strong> du <a href="./../tps/Modèle (Partie A).pdf" target="_blank" rel="noopener">Modèle (Partie A).pdf</a>, avec l&#39;exemple <strong>Les Technologies, 2020</strong>.</p><p>Une citation sert à intégrer dans le texte une idée, une information ou un extrait provenant d&#39;une source (même lorsque reformulée).</p><p>Une citation apparaît normalement entre parenthèses suite au texte et doit correspondre à une source qui pourra ensuite être indiquée dans la bibliographie.</p><hr><h4 id="note-explicative-en-bas-de-page" tabindex="-1">Note explicative en bas de page <a class="header-anchor" href="#note-explicative-en-bas-de-page" aria-label="Permalink to &quot;Note explicative en bas de page&quot;">​</a></h4><p>Insérer <strong>au moins une note explicative en bas de page</strong>.</p><p>L&#39;exemple de note de bas de page se trouve à la <strong>page 5</strong> du <a href="./../tps/Modèle (Partie A).pdf" target="_blank" rel="noopener">Modèle (Partie A).pdf</a>.</p><p>La note de bas de page sert à ajouter une explication, une précision ou un commentaire complémentaire sans alourdir le texte principal.</p><p>Elle ne remplace pas une citation ni une entrée de bibliographie.</p><hr><h4 id="tableau" tabindex="-1">Tableau <a class="header-anchor" href="#tableau" aria-label="Permalink to &quot;Tableau&quot;">​</a></h4><p>Créer un tableau <strong>identique à celui à la page 6 du <a href="./../tps/Modèle (Partie A).pdf" target="_blank" rel="noopener">Modèle (Partie A).pdf</a></strong> :</p><p>Référence visuelle du tableau : <img src="'+o+'" alt="Exemple du tableau du modèle"></p><ul><li>avec un <strong>style différent du style par défaut</strong></li><li>avec une <strong>légende significative</strong></li></ul><p>Ce tableau pourra être utilisé dans la partie B pour présenter les organisations.</p><hr><h4 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h4><p>Insérer <strong>au moins deux images de votre choix</strong> avec :</p><ul><li>une <strong>légende significative qui est un lien cliquable vers la source de l&#39;image</strong></li></ul><p>Le positionnement des images doit être <strong>identique à celui du <a href="./../tps/Modèle (Partie A).pdf" target="_blank" rel="noopener">Modèle (Partie A).pdf</a></strong>.</p><hr><h3 id="en-tetes-et-pieds-de-page" tabindex="-1">En-têtes et pieds de page <a class="header-anchor" href="#en-tetes-et-pieds-de-page" aria-label="Permalink to &quot;En-têtes et pieds de page&quot;">​</a></h3><p>La page de présentation <strong>ne doit pas contenir d’en-tête ni de pied de page</strong>.</p><p>Pages paires :</p><ul><li>en-tête à droite → titre du travail</li><li>pied de page à droite → numéro de page</li></ul><p>Pages impaires :</p><ul><li>en-tête à gauche → votre nom</li><li>pied de page à gauche → numéro de page</li></ul><p>Encore une fois, <strong>référez-vous au <a href="./../tps/Modèle (Partie A).pdf" target="_blank" rel="noopener">Modèle (Partie A).pdf</a> pour obtenir une image claire de ce qui est requis.</strong></p><hr><h3 id="fichiers-a-produire" tabindex="-1">Fichiers à produire <a class="header-anchor" href="#fichiers-a-produire" aria-label="Permalink to &quot;Fichiers à produire&quot;">​</a></h3><p>Partie A :</p><ul><li><code>TP3-A_Modele_Prenom_Nom.dotx</code> <strong>(DOTX, PAS DOCX car c&#39;est un modèle/gabarit)</strong></li><li><code>TP3-A_Modele_Prenom_Nom.pdf</code></li></ul><p>Les fichiers doivent être nommés <strong>exactement</strong> comme indiqué ci-dessus. Remplacez <code>Prenom</code> et <code>Nom</code> par votre prénom et votre nom.</p><p>Le document Word de la partie A doit être <strong>exporté en PDF</strong> avant la remise.</p><hr><h2 id="partie-b-—-rapport-sur-des-organisations" tabindex="-1">Partie B — Rapport sur des organisations <a class="header-anchor" href="#partie-b-—-rapport-sur-des-organisations" aria-label="Permalink to &quot;Partie B — Rapport sur des organisations&quot;">​</a></h2><p>Dans cette partie, vous devez <strong>utiliser le modèle créé dans la partie A</strong> (créez une copie du modèle et renommez-la <code>TP3-B_Rapport_Prenom_Nom.docx</code>).</p><p>Un exemple complet d&#39;analyse d&#39;une entreprise se trouve ici : <a href="./../modules/04-analyse-info/04-etude-cgi">Étude de cas — CGI à Québec</a>.</p><p>Le rapport doit analyser <strong>trois organisations employant des informaticiens</strong>.</p><p>Vous devez choisir <strong>2 sujets parmi les 3 suivants</strong> :</p><ul><li><strong>Entreprise visitée #1</strong></li><li><strong>Entreprise visitée #2</strong></li><li><strong><a href="https://www.quebec.ca/gouvernement/ministeres-organismes/cybersecurite-numerique" target="_blank" rel="noreferrer">Ministère de la Cybersécurité et du Numérique</a></strong></li></ul><p>Vous devez ensuite ajouter :</p><ul><li><strong>Une entreprise de votre choix située dans la région de Québec et qui oeuvre dans un secteur d&#39;activité différent de celui des deux entreprises précédentes</strong></li></ul><p>Pour connaître les entreprises qui seront visitées ainsi que la conférence du Ministère, consultez le calendrier de votre groupe : <a href="./../plan-cours/calendrier-gr1">groupe 1 (jeudi)</a> ou <a href="./../plan-cours/calendrier-gr2">groupe 2 (mardi)</a>.</p><hr><h3 id="introduction-max-1-demi-page" tabindex="-1">Introduction (max 1 demi page) <a class="header-anchor" href="#introduction-max-1-demi-page" aria-label="Permalink to &quot;Introduction (max 1 demi page)&quot;">​</a></h3><p>Présenter :</p><ul><li>le but du travail</li><li>le contexte</li><li>les sections du rapport</li></ul><p>Structure imposée pour votre introduction :</p><ul><li>sujet amené (introduire le sujet sans le nommer)</li><li>sujet posé (présenter clairement le sujet)</li><li>sujet divisé (présenter la structure du développement, c&#39;est-à-dire les organisations qui seront à l&#39;étude plus bas dans votre travail)</li></ul><p>Guide de référence : <a href="https://www.alloprof.qc.ca/fr/eleves/bv/francais/l-introduction-du-texte-argumentatif-f1450#introduction" target="_blank" rel="noreferrer">Structure du texte argumentatif (Alloprof)</a>.</p><hr><h3 id="organisations-selectionnees-max-1-demi-page" tabindex="-1">Organisations sélectionnées (max 1 demi page) <a class="header-anchor" href="#organisations-selectionnees-max-1-demi-page" aria-label="Permalink to &quot;Organisations sélectionnées (max 1 demi page)&quot;">​</a></h3><p>Compléter le tableau créé dans votre modèle (ajouter des colonnes au besoin).</p><p>Référence visuelle du tableau à compléter : <img src="'+n+'" alt="Exemple de tableau pour les entreprises"></p><p>Inclure :</p><ul><li>nom de l&#39;organisation (<strong>lien cliquable</strong> vers le site Web)</li><li>secteur d&#39;activité de l&#39;organisation</li><li>localisation du siège social</li><li>date de fondation</li></ul><p>Le tableau doit avoir <strong>une légende significative</strong>.</p><hr><h3 id="presentation-des-organisations-environ-1-2-pages-par-organisation" tabindex="-1">Présentation des organisations (environ 1 - 2 pages par organisation) <a class="header-anchor" href="#presentation-des-organisations-environ-1-2-pages-par-organisation" aria-label="Permalink to &quot;Présentation des organisations (environ 1 - 2 pages par organisation)&quot;">​</a></h3><p>Créer une <strong>section</strong> pour <strong>chaque organisation</strong>.</p><p>Pour chaque organisation, présentez de façon concise en <strong>sous-sections</strong> :</p><ul><li>une brève description de l’organisation incluant sa mission, ses valeurs ainsi que le <strong>type d&#39;organisation (privée, publique, OBNL)</strong></li><li>son <strong>domaine informatique principal</strong> ou celui actuellement en demande</li><li><strong>un poste en informatique différent pour chaque organisation</strong> que l’on peut y retrouver (section carrières) <ul><li>quelques <strong>tâches, responsabilités et compétences</strong> associées au poste <strong>dans cette organisation</strong>; il ne s&#39;agit pas d&#39;une description générale du métier</li></ul></li></ul><p>Le poste choisi doit être différent d&#39;une organisation à l&#39;autre. Vous ne pouvez pas réutiliser le même poste pour plusieurs organisations.</p><p>Ajouter aussi pour chaque organisation analysée :</p><ul><li>le <strong>logo</strong></li><li>une <strong>photo du bâtiment ou des bureaux</strong></li></ul><p>Chaque image doit avoir <strong>une légende</strong>.</p><p>Appuyez votre texte avec <strong>des sources fiables et variées à l&#39;aide de citations</strong>. Si la section carrières de l&#39;organisation est vide ou peu détaillée, vous pouvez aussi déduire l&#39;information à partir d&#39;offres d&#39;emploi pour des postes similaires dans des organisations comparables, trouvées sur Indeed, LinkedIn, Glassdoor, etc.</p><div class="warning custom-block"><p class="custom-block-title">Attention aux sources</p><p>Il est <strong>obligatoire</strong> de citer vos sources en utilisant des <strong>citations</strong> dans le texte.</p><p><strong>Pas de sources = pas de points</strong> pour cette section du travail.</p></div><hr><h3 id="les-organisations-en-informatique-a-quebec-environ-1-demi-page" tabindex="-1">Les organisations en informatique à Québec (environ 1 demi page) <a class="header-anchor" href="#les-organisations-en-informatique-a-quebec-environ-1-demi-page" aria-label="Permalink to &quot;Les organisations en informatique à Québec (environ 1 demi page)&quot;">​</a></h3><p>Comparer les organisations étudiées.</p><p>Identifier :</p><ul><li>leurs similarités</li><li>leurs différences</li></ul><hr><h3 id="conclusion-environ-1-demi-page" tabindex="-1">Conclusion (environ 1 demi page) <a class="header-anchor" href="#conclusion-environ-1-demi-page" aria-label="Permalink to &quot;Conclusion (environ 1 demi page)&quot;">​</a></h3><p>La conclusion doit :</p><ul><li>résumer les idées principales</li><li>présenter une réflexion personnelle sur le domaine de l’informatique</li></ul><p>Questions pour vous guider :</p><ul><li>Qu’avez-vous retenu de votre analyse des organisations choisies ?</li><li>Quel type d’entreprise, de secteur d’activité ou de poste vous semble le plus intéressant, et pourquoi ?</li><li>En quoi cette recherche vous aide-t-elle à mieux comprendre le milieu de l’informatique au Québec ?</li></ul><hr><h3 id="bibliographie-sur-une-page-a-part" tabindex="-1">Bibliographie (sur une page à part) <a class="header-anchor" href="#bibliographie-sur-une-page-a-part" aria-label="Permalink to &quot;Bibliographie (sur une page à part)&quot;">​</a></h3><p>La bibliographie doit contenir <strong>toutes les sources utilisées</strong>.</p><p>Utiliser le <strong>style APA</strong> de façon cohérente dans tout le document.</p><p>Tutoriel Word (bibliographie, citations et références) : <a href="https://support.microsoft.com/fr-fr/office/cr%C3%A9er-une-bibliographie-des-citations-et-des-r%C3%A9f%C3%A9rences-17686589-4824-4940-9c69-342c289fa2a5?ui=fr-fr&amp;rs=fr-fr&amp;ad=fr" target="_blank" rel="noreferrer">Microsoft Support</a>.</p><hr><h3 id="citations" tabindex="-1">Citations <a class="header-anchor" href="#citations" aria-label="Permalink to &quot;Citations&quot;">​</a></h3><p>Créer <strong>au moins deux citations</strong> par organisation analysée dans le document.</p><p>Chaque citation dans le texte doit être faite en <strong>style APA</strong> et correspondre à une source présentée dans la bibliographie. Les sources doivent être variées (pas uniquement le site Web de l&#39;entreprise analysée). Les <a href="./../modules/04-analyse-info/01-recherche#quelles-sources-utiliser">sources suivantes</a> vous seront utiles.</p><p>Tutoriel Word (bibliographie, citations et références) : <a href="https://support.microsoft.com/fr-fr/office/cr%C3%A9er-une-bibliographie-des-citations-et-des-r%C3%A9f%C3%A9rences-17686589-4824-4940-9c69-342c289fa2a5?ui=fr-fr&amp;rs=fr-fr&amp;ad=fr" target="_blank" rel="noreferrer">Microsoft Support</a>.</p><hr><h3 id="fichiers-a-produire-1" tabindex="-1">Fichiers à produire <a class="header-anchor" href="#fichiers-a-produire-1" aria-label="Permalink to &quot;Fichiers à produire&quot;">​</a></h3><p>Partie B :</p><ul><li><code>TP3-B_Rapport_Prenom_Nom.docx</code></li><li><code>TP3-B_Rapport_Prenom_Nom.pdf</code></li></ul><p>Les fichiers doivent être nommés <strong>exactement</strong> comme indiqué ci-dessus. Remplacez <code>Prenom</code> et <code>Nom</code> par votre prénom et votre nom.</p><p>Le document Word de la partie B doit être <strong>exporté en PDF</strong> avant la remise.</p><hr><h2 id="revision-linguistique" tabindex="-1">Révision linguistique <a class="header-anchor" href="#revision-linguistique" aria-label="Permalink to &quot;Révision linguistique&quot;">​</a></h2><p>Avant la remise :</p><ul><li>utiliser <strong>Antidote</strong> : <a href="https://services.druide.com/connexion/externe?app=aw&amp;langueDefaut=fr" target="_blank" rel="noreferrer">connexion Druide</a></li><li>corriger l’orthographe</li><li>corriger la syntaxe</li></ul><p>⚠️ Des pénalités peuvent être appliquées pour les fautes de français.</p><hr><h2 id="remise" tabindex="-1">Remise <a class="header-anchor" href="#remise" aria-label="Permalink to &quot;Remise&quot;">​</a></h2><p>Fichiers à remettre :</p><p>Les fichiers doivent être nommés <strong>exactement</strong> comme suit. Remplacez <code>Prenom</code> et <code>Nom</code> par votre prénom et votre nom.</p><p><strong>Partie A</strong></p><ul><li><code>TP3-A_Modele_Prenom_Nom.dotx</code></li><li><code>TP3-A_Modele_Prenom_Nom.pdf</code></li></ul><p><strong>Partie B</strong></p><ul><li><code>TP3-B_Rapport_Prenom_Nom.docx</code></li><li><code>TP3-B_Rapport_Prenom_Nom.pdf</code></li></ul><p>Tous les fichiers doivent être remis dans :</p><p><strong>un fichier ZIP sur Léa</strong></p><hr><h2 id="ponderation" tabindex="-1">Pondération <a class="header-anchor" href="#ponderation" aria-label="Permalink to &quot;Pondération&quot;">​</a></h2><p>Valeur du travail : <strong>20 %</strong></p><p>Date limite : <strong>voir Léa</strong></p>',167)])])}const f=r(s,[["render",l]]);export{h as __pageData,f as default};
